return {
    ["PointCloud"] = function(p1, p2) --[[ Name: PointCloud, Line 12 ]]
        local v3 = p1[1]
        local v4 = p1[1]:Dot(p2)
        for v5 = 2, #p1 do
            local v6 = p1[v5]:Dot(p2)
            if v4 < v6 then
                v3 = p1[v5]
                v4 = v6
            end
        end
        return v3
    end,
    ["Cylinder"] = function(p7, p8) --[[ Name: Cylinder, Line 23 ]]
        local v9, v10 = unpack(p7)
        local v11 = v9:VectorToObjectSpace(p8)
        local v12 = v10.y
        local v13 = v10.z
        local v14 = math.min(v12, v13)
        local v15 = v11:Dot(Vector3.new(1, 0, 0))
        local v16 = v10.x
        local v17 = Vector3.new(v16, 0, 0)
        local v18
        if v15 == 0 then
            v18 = v11.Unit * v14
        else
            local v19 = v15 > 0 and v17 and v17 or -v17
            v18 = v19 + (Vector3.new(0, 0, 0) + -(Vector3.new(0, 0, 0) - v19):Dot(Vector3.new(1, 0, 0)) / v11:Dot(Vector3.new(1, 0, 0)) * v11 - v19).Unit * v14
        end
        return v9:PointToWorldSpace(v18)
    end,
    ["Ellipsoid"] = function(p20, p21) --[[ Name: Ellipsoid, Line 40 ]]
        local v22, v23 = unpack(p20)
        return v22:PointToWorldSpace(v23 * (v23 * v22:VectorToObjectSpace(p21)).Unit)
    end
}